       function getFieldError(field, input) {
         const value = input.value.trim();

         if (field.required && value === "") {
           return field.errorMessage;
         }

         if (field.type === "email" && value !== "" && !input.validity.valid) {
           return field.errorMessage;
         }

         if (field.type === "tel" && value !== "" && !/^\+?[0-9\s().-]{7,}$/.test(value)) {
           return field.errorMessage;
         }

         return "";
