     <script>
       const fields = [
         {
           id: "full-name",
           name: "fullName",
           label: "Full name",
           type: "text",
           autocomplete: "name",
           required: true,
           placeholder: "Alex Morgan",
           errorMessage: "Error: Enter your full name."
         },
         {
           id: "email",
           name: "email",
           label: "Email address",
           type: "email",
           autocomplete: "email",
           required: true,
           placeholder: "alex@example.com",
           errorMessage: "Error: Enter a valid email address, such as alex@example.com."
         },
         {
           id: "phone",
           name: "phone",
           label: "Phone number",
           type: "tel",
           autocomplete: "tel",
           required: false,
           placeholder: "+1 555 123 4567",
           helperText: "Use international format when possible, for example +1 555 123 4567.",
           errorMessage: "Error: Enter a phone number using digits, spaces, parentheses, hyphens, or a leading plus sign."
         }
       ];

       function Field({ id, name, label, type, autocomplete, required, placeholder, helperText }) {
         const describedBy = [
           helperText ? `${id}-help` : "",
           `${id}-error`
         ].filter(Boolean).join(" ");

         return `
           <div class="form-field">
             <label for="${id}">
               ${label}${required ? ' <span class="required-marker" aria-hidden="true">*</span>' : " (optional)"}
             </label>
             <input
               id="${id}"
               name="${name}"
               type="${type}"
               autocomplete="${autocomplete}"
               placeholder="${placeholder}"
               aria-describedby="${describedBy}"
               ${required ? "required" : ""}
             >
             ${helperText ? `<p class="helper-text" id="${id}-help">${helperText}</p>` : ""}
             <p class="error-message" id="${id}-error"></p>
           </div>
         `;
       }

       function ContactForm() {
         return `
           <section class="support-card" aria-labelledby="support-title">
             <p class="eyebrow">Support</p>
             <h1 id="support-title">How can we help?</h1>
             <p class="intro">
               Share your contact details and our support team will get back to you as soon as possible.
             </p>
             <form id="support-form" novalidate>
               <p class="required-note"><span class="required-marker" aria-hidden="true">*</span> Required fields</p>
               ${fields.map(Field).join("")}
               <button type="submit">Send request</button>
               <p class="status-message" id="form-status" role="status" aria-live="polite"></p>
             </form>
           </section>
         `;
       }

       function getFieldError(field, input) {
         const value = input.value.trim();

         if (field.required && value === "") {
           return field.errorMessage;
         }

         if (field.type === "email" && value !== "" && !input.validity.valid) {
           return field.errorMessage;
         }

         if (field.type === "tel" && value !== "" && !/^\+?[0-9\s().-]{7,}$/.test(value)) {
           return field.errorMessage;
         }

         return "";
       }

       function setFieldError(input, message) {
         const error = document.getElementById(`${input.id}-error`);
         error.textContent = message;

         if (message) {
           input.setAttribute("aria-invalid", "true");
         } else {
           input.removeAttribute("aria-invalid");
         }
       }

       function validateForm(form) {
         let firstInvalid = null;

         fields.forEach((field) => {
           const input = form.elements[field.name];
           const error = getFieldError(field, input);
           setFieldError(input, error);

           if (error && firstInvalid === null) {
             firstInvalid = input;
           }
         });

         return firstInvalid;
       }

       function attachFormBehavior() {
         const form = document.getElementById("support-form");
         const status = document.getElementById("form-status");

         form.addEventListener("submit", (event) => {
           event.preventDefault();
           status.textContent = "";

           const firstInvalid = validateForm(form);

           if (firstInvalid) {
             firstInvalid.focus();
             return;
           }

           form.reset();
           fields.forEach((field) => setFieldError(form.elements[field.name], ""));
           status.textContent = "Thanks, your support request is ready to send.";
