      .skip-link:focus {
        transform: translateY(0);
        outline: 3px solid #ffffff;
        outline-offset: 3px;
      }

      main {
        display: grid;
        min-height: 100vh;
        place-items: center;
        padding: clamp(1rem, 4vw, 3rem);
      }

      .support-card {
        width: min(100%, 42rem);
        border: 1px solid rgba(255, 255, 255, 0.1);
        border-radius: 1.5rem;
        padding: clamp(1.25rem, 4vw, 2.5rem);
        background:
          linear-gradient(180deg, rgba(255, 255, 255, 0.055), rgba(255, 255, 255, 0.02)),
          var(--panel);
        box-shadow: var(--shadow);
      }

      .eyebrow {
        margin: 0 0 0.6rem;
        color: var(--accent-strong);
        font-size: 0.82rem;
        font-weight: 800;
        letter-spacing: 0.14em;
        text-transform: uppercase;
      }

      h1 {
        margin: 0;
        font-size: clamp(2rem, 7vw, 3.75rem);
        line-height: 0.95;
        letter-spacing: -0.06em;
      }

      .intro {
        margin: 1rem 0 0;
        max-width: 36rem;
        color: var(--muted);
        font-size: 1.05rem;
      }

      form {
        display: grid;
        gap: 1.2rem;
        margin-top: 2rem;
      }

      .required-note {
        margin: 0;
        color: var(--muted);
        font-size: 0.95rem;
      }

      .form-field {
        display: grid;
        gap: 0.45rem;
      }

      label {
        color: #eef4ff;
        font-weight: 750;
      }

      .required-marker {
        color: var(--accent-strong);
        font-weight: 900;
      }

      input {
        width: 100%;
        border: 1px solid var(--border);
        border-radius: 0.9rem;
        padding: 0.95rem 1rem;
        color: var(--text);
        background: var(--panel-strong);
        font: inherit;
        transition:
          border-color 160ms ease,
          box-shadow 160ms ease,
          background 160ms ease;
      }

      input::placeholder {
        color: #7f8da3;
      }

      input:hover {
        border-color: #536783;
      }

      input:focus {
        border-color: var(--accent);
        outline: 3px solid rgba(104, 225, 253, 0.42);
        outline-offset: 2px;
        box-shadow: 0 0 0 6px rgba(104, 225, 253, 0.08);
      }

      input[aria-invalid="true"] {
        border-color: var(--danger);
        box-shadow: 0 0 0 1px rgba(255, 154, 154, 0.4);
      }

      .helper-text,
      .error-message,
      .status-message {
        margin: 0;
        font-size: 0.94rem;
      }

      .helper-text {
        color: var(--muted);
      }

      .error-message {
        color: var(--danger);
        font-weight: 700;
      }

      .error-message:empty,
      .status-message:empty {
        display: none;
      }

      button {
        width: fit-content;
        min-width: 10rem;
        border: 0;
        border-radius: 999px;
        padding: 0.95rem 1.35rem;
        color: #041118;
        background: linear-gradient(135deg, var(--accent) 0%, var(--accent-strong) 100%);
        box-shadow: 0 16px 36px rgba(104, 225, 253, 0.25);
        cursor: pointer;
        font: inherit;
        font-weight: 850;
      }

      button:hover {
        filter: brightness(1.05);
      }

      button:focus {
        outline: 3px solid #ffffff;
        outline-offset: 4px;
      }

      .status-message {
        min-height: 1.5rem;
        color: var(--accent-strong);
        font-weight: 750;
      }

      @media (max-width: 36rem) {
        button {
          width: 100%;
        }
      }

      @media (forced-colors: active) {
        body,
        .support-card,
        input,
        button {
          forced-color-adjust: auto;
        }

        .support-card,
        input {
          border: 1px solid CanvasText;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>
    <main id="main-content"></main>

    <script>
      const fields = [
        {
          id: "full-name",
          name: "fullName",
          label: "Full name",
          type: "text",
          autocomplete: "name",
          required: true,
          placeholder: "Alex Morgan",
          errorMessage: "Error: Enter your full name."
        },
        {
          id: "email",
          name: "email",
          label: "Email address",
          type: "email",
          autocomplete: "email",
          required: true,
          placeholder: "alex@example.com",
          errorMessage: "Error: Enter a valid email address, such as alex@example.com."
        },
        {
          id: "phone",
          name: "phone",
          label: "Phone number",
          type: "tel",
          autocomplete: "tel",
          required: false,
          placeholder: "+1 555 123 4567",
          helperText: "Use international format when possible, for example +1 555 123 4567.",
          errorMessage: "Error: Enter a phone number using digits, spaces, parentheses, hyphens, or a leading plus sign."
        }
      ];

      function Field({ id, name, label, type, autocomplete, required, placeholder, helperText }) {
        const describedBy = [
          helperText ? `${id}-help` : "",
          `${id}-error`
        ].filter(Boolean).join(" ");

        return `
          <div class="form-field">
            <label for="${id}">
              ${label}${required ? ' <span class="required-marker" aria-hidden="true">*</span>' : " (optional)"}
            </label>
            <input
              id="${id}"
              name="${name}"
              type="${type}"
              autocomplete="${autocomplete}"
              placeholder="${placeholder}"
              aria-describedby="${describedBy}"
              ${required ? "required" : ""}
            >
            ${helperText ? `<p class="helper-text" id="${id}-help">${helperText}</p>` : ""}
            <p class="error-message" id="${id}-error"></p>
          </div>
        `;
      }

      function ContactForm() {
        return `
          <section class="support-card" aria-labelledby="support-title">
            <p class="eyebrow">Support</p>
            <h1 id="support-title">How can we help?</h1>
            <p class="intro">
              Share your contact details and our support team will get back to you as soon as possible.
            </p>
            <form id="support-form" novalidate>
              <p class="required-note"><span class="required-marker" aria-hidden="true">*</span> Required fields</p>
              ${fields.map(Field).join("")}
              <button type="submit">Send request</button>
              <p class="status-message" id="form-status" role="status" aria-live="polite"></p>
            </form>
          </section>
        `;
      }

      function getFieldError(field, input) {
        const value = input.value.trim();

        if (field.required && value === "") {
          return field.errorMessage;
        }

        if (field.type === "email" && value !== "" && !input.validity.valid) {
          return field.errorMessage;
        }

        if (field.type === "tel" && value !== "" && !/^\+?[0-9\s().-]{7,}$/.test(value)) {
          return field.errorMessage;
        }

        return "";
      }

      function setFieldError(input, message) {
        const error = document.getElementById(`${input.id}-error`);
        error.textContent = message;

        if (message) {
          input.setAttribute("aria-invalid", "true");
        } else {
          input.removeAttribute("aria-invalid");
        }
      }

      function validateForm(form) {
        let firstInvalid = null;

        fields.forEach((field) => {
          const input = form.elements[field.name];
          const error = getFieldError(field, input);
          setFieldError(input, error);

          if (error && firstInvalid === null) {
            firstInvalid = input;
          }
        });

        return firstInvalid;
      }

      function attachFormBehavior() {
        const form = document.getElementById("support-form");
        const status = document.getElementById("form-status");

        form.addEventListener("submit", (event) => {
          event.preventDefault();
          status.textContent = "";

          const firstInvalid = validateForm(form);

          if (firstInvalid) {
            firstInvalid.focus();
            return;
          }

          form.reset();
          fields.forEach((field) => setFieldError(form.elements[field.name], ""));
          status.textContent = "Thanks, your support request is ready to send.";
        });

        fields.forEach((field) => {
          const input = form.elements[field.name];

          input.addEventListener("input", () => {
            if (input.getAttribute("aria-invalid") === "true") {
              setFieldError(input, getFieldError(field, input));
            }
          });
        });
      }

      document.getElementById("main-content").innerHTML = ContactForm();
      attachFormBehavior();
    </script>
  </body>
</html>
